// Polaroid placeholder component
function Polaroid({ label, size = "md", bg = "#e8e5e0" }) {
  const sizes = {
    sm: { w: 90, h: 110, inner: 70, labelSize: 9 },
    md: { w: 130, h: 155, inner: 100, labelSize: 10 },
    lg: { w: 160, h: 195, inner: 130, labelSize: 11 },
  };
  const s = sizes[size];
  return (
    <div style={{
      width: s.w, background: "#fff",
      padding: "8px 8px 24px",
      boxShadow: "2px 3px 12px rgba(0,0,0,0.13)",
      display: "inline-block",
      flexShrink: 0,
    }}>
      <div style={{
        width: "100%", height: s.inner,
        background: bg,
        display: "flex", alignItems: "center", justifyContent: "center",
      }}>
        <span style={{ fontSize: 22, opacity: 0.4 }}>📷</span>
      </div>
      {label && (
        <div style={{
          textAlign: "center", marginTop: 6,
          fontSize: s.labelSize, fontFamily: "'Jost', sans-serif",
          color: "#888", letterSpacing: "0.08em",
        }}>{label}</div>
      )}
    </div>
  );
}

